/// A typed reason an invitation cannot be accepted.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum AcceptFailureFfi {
    /// The invitation can never be accepted on this device (its KeyPackage's
    /// private bundle is gone, or the Welcome is invalid or already
    /// processed); only a new invitation can add this device. The invitation
    /// has already been resolved like a decline.
    NeedsNewInvite,
    /// The invitation would replace a circle this device still holds (a
    /// removal it never saw, or a fork), which needs the user's explicit
    /// confirmation. The invitation stays held.
    RejoinConfirmationRequired,
}

/// Whether a fetched KeyPackage can be invited (FFI mirror of
/// [`haven_core::nostr::mls::types::KeyPackageAdmission`]).
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum KeyPackageAdmissionFfi {
    /// MDK admits it for the target.
    Admissible,
    /// A pre-migration package: the person needs to update Haven.
    NeedsUpdate,
    /// It cannot be invited for any other reason.
    Unusable,
}

impl From<haven_core::nostr::mls::types::KeyPackageAdmission> for KeyPackageAdmissionFfi {
    fn from(admission: haven_core::nostr::mls::types::KeyPackageAdmission) -> Self {
        use haven_core::nostr::mls::types::KeyPackageAdmission as A;
        match admission {
            A::Admissible => Self::Admissible,
            A::NeedsUpdate => Self::NeedsUpdate,
            A::Unusable => Self::Unusable,
        }
    }
}

/// Pending invitation to join a circle (FFI-friendly).
#[derive(Clone)]
pub struct InvitationFfi {
    /// MLS group ID.
    pub mls_group_id: Vec<u8>,
    /// Circle name.
    pub circle_name: String,
    /// Public key (hex) of who invited us.
    pub inviter_pubkey: String,
    /// The inviter's public key in NIP-19 bech32 format (`npub1...`).
    ///
    /// A derived encoding of [`Self::inviter_pubkey`], carried alongside it
    /// rather than replacing it: the hex is the cache key and the identity
    /// comparison, the npub is the only form a user can check against what the
    /// inviter actually handed them. Deciding whether to join a stranger's
    /// live-location circle is exactly where that check has to be possible.
    pub inviter_npub: String,
    /// When we were invited (Unix timestamp).
    pub invited_at: i64,
}

/// Redacting `Debug` matching the sibling `*Ffi` types (`ContactFfi`,
/// [`CircleMemberFfi`]): the inviter is named by a salted handle, and the
/// circle's name and the invitation instant do not print. `inviter_pubkey` and
/// `inviter_npub` are the same 32 bytes, so both collapse onto one handle —
/// aliasing one alone would alias nothing (Security Rules 6/15).
impl std::fmt::Debug for InvitationFfi {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        f.debug_struct("InvitationFfi")
            .field("mls_group_id", &"<redacted>")
            .field("circle_name", &"<redacted>")
            .field(
                "inviter",
                &haven_core::log_alias::peer(PeerPubkey(&self.inviter_pubkey)),
            )
            .finish()
    }
}

impl From<&CoreInvitation> for InvitationFfi {
    fn from(i: &CoreInvitation) -> Self {
        Self {
            mls_group_id: i.mls_group_id.as_slice().to_vec(),
            circle_name: i.circle_name.clone(),
            inviter_npub: hex_to_npub(&i.inviter_pubkey),
            inviter_pubkey: i.inviter_pubkey.clone(),
            invited_at: i.invited_at,
        }
    }
}

impl From<CoreInvitation> for InvitationFfi {
    fn from(i: CoreInvitation) -> Self {
        Self::from(&i)
    }
}

/// Key package bundle for publishing (FFI-friendly).
///
/// A member's key package with their inbox relay list (FFI-friendly).
///
/// Used when adding members to a circle. The Welcome goes to the inbox relays
/// alone; all three lists are relays a new circle avoids.
#[derive(Clone)]
pub struct MemberKeyPackageFfi {
    /// The key package event JSON (kind 30443).
    pub key_package_json: String,
    /// Relay URLs from the member's inbox relay list (kind 10050).
    pub inbox_relays: Vec<String>,
    /// Fallback relay URLs: the read-capable set of the NIP-65 relay list
    /// (kind 10002).
    pub nip65_relays: Vec<String>,
    /// The write-capable set of the same NIP-65 list. With the other two, the
    /// relays a create that names none avoids for the circle.
    pub nip65_write_relays: Vec<String>,
    /// The account the key package was verified to belong to, as an npub: its
    /// signer, its MLS credential and the pubkey that was asked for, all one
    /// (`fetch_member_keypackage` sets it, never from the request). Passed back
    /// into `create_circle` / `add_members_to_circle`, it must name the
    /// package's signer, because that is who the Welcome reaches.
    pub author_npub: String,
}

impl std::fmt::Debug for MemberKeyPackageFfi {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        // A relay-list SIZE is a fingerprint of a customised pool (Rule 15),
        // so presence is all that renders.
        f.debug_struct("MemberKeyPackageFfi")
            .field("key_package_json", &"<redacted>")
            .field("has_inbox_relays", &!self.inbox_relays.is_empty())
            .field("has_nip65_relays", &!self.nip65_relays.is_empty())
            .field(
                "has_nip65_write_relays",
                &!self.nip65_write_relays.is_empty(),
            )
            .finish()
    }
}

/// What [`RelayManagerFfi::create_circle_driven`] did: the circle, unless
