    fn built_relay_list(targets: usize) -> BuiltRelayListEventFfi {
        BuiltRelayListEventFfi {
            event_json: Some(format!(r#"{{"id":"{HEX_ID}"}}"#)),
            event_id_hex: Some(HEX_ID.to_string()),
            targets: vec![RELAY.to_string(); targets],
            kind: Some(10_002),
            created_at_secs: Some(INSTANT),
            suppressed: false,
            awaiting_reset_acknowledgement: false,
        }
    }

    fn built_unpublish(targets: usize) -> BuiltUnpublishFfi {
        BuiltUnpublishFfi {
            replacement_event_json: Some(format!(r#"{{"id":"{HEX_ID}"}}"#)),
            deletion_event_json: Some(format!(r#"{{"id":"{HASH_HEX}"}}"#)),
            targets: vec![RELAY.to_string(); targets],
            suppressed: false,
        }
    }

    fn gift_wrap_fetch(events: usize) -> RelayGiftWrapFetchFfi {
        RelayGiftWrapFetchFfi {
            relay_url: RELAY.to_string(),
            responded: true,
            events: vec![TEXT.to_string(); events],
        }
    }

    /// An inner backend that records the targets it was handed, so the wrapper's
    /// forwarding can be observed rather than inferred.
    struct RecordingLogger(std::sync::Mutex<Vec<String>>);

    impl log::Log for RecordingLogger {
        fn enabled(&self, _metadata: &log::Metadata<'_>) -> bool {
            true
        }

        fn log(&self, record: &log::Record<'_>) {
            self.0
                .lock()
                .expect("a fresh lock is never poisoned")
                .push(record.target().to_string());
        }

        fn flush(&self) {}
    }

    /// Offers one `TRACE` record under `target` to `logger`, returning what its
    /// `enabled` said. `format_args!` cannot outlive a `let`, so the record is
    /// built and passed in one expression.
    fn offer_record(logger: &impl log::Log, target: &str) -> bool {
        let metadata = log::Metadata::builder()
            .target(target)
            .level(log::Level::Trace)
            .build();
        let enabled = logger.enabled(&metadata);
        logger.log(
            &log::Record::builder()
                .metadata(metadata)
                .args(format_args!("a record"))
                .build(),
        );
        enabled
    }

    #[test]
    fn the_ffi_log_target_is_this_crates_own_name() {
        // The allowlist is keyed to the crate name, and a rename in Cargo.toml
        // would silence every FFI log line rather than fail to compile.
        assert_eq!(
            super::HAVEN_FFI_LOG_TARGET,
            env!("CARGO_PKG_NAME").replace('-', "_"),
            "this crate's log target must be its own crate name"
        );
    }

    #[test]
    fn the_release_log_cap_is_warn_and_the_debug_cap_is_debug() {
        // Both arms are exercised from either profile because the cap is a
        // function of `cfg!(debug_assertions)` rather than two `#[cfg]` bodies —
        // a release-only body could not be tested by a dev-profile `cargo test`.
        assert_eq!(
            super::max_log_level(true),
            log::LevelFilter::Debug,
            "a debug build must still show Haven's own `debug!` lines — the E2E \
             lanes read them"
        );
        assert_eq!(
            super::max_log_level(false),
            log::LevelFilter::Warn,
            "a shipped build must emit nothing below `warn!`, which is what makes \
             the surviving level's identifier-freedom the whole guarantee"
        );
    }

    #[test]
    fn log_target_allowed_admits_only_havens_own_crates() {
        for target in [
            "haven_core",
            "haven_core::relay::live_sync",
            "rust_lib_haven",
            "rust_lib_haven::api",
        ] {
            assert!(
                super::log_target_allowed(target),
                "{target} is Haven's own and must keep logging"
            );
        }
        for target in [
            // A dependency that logs a relay host at TRACE, one that logs relay
            // URLs at DEBUG, the one that logged raw DB-key bytes, a transitive
            // HTTP stack, the bridge itself — and an empty target.
            "tungstenite",
            "tungstenite::handshake::client",
            "nostr_relay_pool",
            "nostr_relay_pool::relay::inner",
            "keyring_core",
            "hyper",
            "flutter_rust_bridge",
            "",
            // The `::` boundary: a crate merely named like ours is not ours.
            "haven_core_extra",
            "rust_lib_haven_extra",
        ] {
            assert!(
                !super::log_target_allowed(target),
                "{target} is not Haven's own and must be silent"
            );
        }
    }

    #[test]
    fn the_target_filter_forwards_only_havens_own_records() {
        let filter = HavenTargetFilter(RecordingLogger(std::sync::Mutex::new(Vec::new())));

        for (target, expected) in [
            ("haven_core::relay::manager", true),
            ("tungstenite::handshake::client", false),
            ("nostr_relay_pool::relay::inner", false),
            ("keyring_core", false),
            ("rust_lib_haven::api", true),
        ] {
            assert_eq!(
                offer_record(&filter, target),
                expected,
                "`enabled` disagreed with the allowlist for {target}"
            );
        }

        assert_eq!(
            *filter.0 .0.lock().expect("a fresh lock is never poisoned"),
            vec![
                "haven_core::relay::manager".to_string(),
                "rust_lib_haven::api".to_string(),
            ],
            "only Haven's own records may reach the backend: `log` is re-checked \
             there because the macros only consult the facade's max level"
        );
    }

    /// A location result carrying every needle a replayed fix can carry.
    fn a_replayed_fix() -> LocationMessageResultFfi {
        LocationMessageResultFfi {
            kind: LocationMessageResultKindFfi::Location,
            location: Some(DecryptedLocationFfi {
                sender_pubkey: HEX_ID.to_string(),
                latitude: LAT,
                longitude: LON,
                geohash: GEOHASH.to_string(),
                timestamp: INSTANT,
                expires_at: INSTANT,
            }),
            mls_group_id: hex::decode(HASH_HEX).expect("hex"),
            epoch: u64::from(COUNTER),
        }
    }

    fn an_evolution(delivered: u32, replayed: usize) -> EvolutionOutcomeFfi {
        EvolutionOutcomeFfi {
            status: PublishStatusFfi::Unresolved,
            refusal: Some(RefusalFfi::EngineHeld),
            welcomes_delivered: delivered,
            welcomes_total: delivered,
            reinvite_owed: true,
            retry_after_ms: Some(u64::from(COUNTER)),
            replayed: (0..replayed).map(|_| a_replayed_fix()).collect(),
            clock_rejected: Some(super::DeviceClockComplaintFfi::Unspecified),
            already_so: Some(true),
        }
    }

    #[test]
    fn the_driver_outcomes_debug_redacts_every_id_count_and_relay() {
        assert_debug_redacted!(an_evolution(COUNTER, 1), "EvolutionOutcomeFfi", NEEDLES);
        assert_magnitude_invisible(
            &format!("{:?}", an_evolution(1, 1)),
            &format!("{:?}", an_evolution(9, 4)),
            "EvolutionOutcomeFfi",
        );
        let repair = RepairOutcomeFfi {
            kind: RepairKindFfi::Rotated,
            rotated: Some(an_evolution(COUNTER, 2)),
            skipped: Some(SkipReasonFfi::RotatedRecently),
            held_by: Some(SendHeldFfi::Leaving),
            refusal: None,
        };
        assert_debug_redacted!(repair, "RepairOutcomeFfi", NEEDLES);
        let ingest = |replayed: usize| IngestOutcomeFfi {
            verdict: ReceiveVerdictFfi::Deferred,
            replayed: (0..replayed).map(|_| a_replayed_fix()).collect(),
            retry_after_ms: Some(u64::from(COUNTER)),
            errored: false,
            refusal: Some(RefusalFfi::SendBlockedByDeparture),
            clock_rejected: Some(super::DeviceClockComplaintFfi::Behind),
        };
        assert_debug_redacted!(ingest(1), "IngestOutcomeFfi", NEEDLES);
        assert_magnitude_invisible(
            &format!("{:?}", ingest(1)),
            &format!("{:?}", ingest(5)),
            "IngestOutcomeFfi",
        );
        let sealed = || super::SealedLocationFfi {
            event: nostr::EventBuilder::new(nostr::Kind::Custom(445), TEXT)
                .tag(nostr::Tag::custom(nostr::TagKind::h(), [HEX_ID]))
                .sign_with_keys(&nostr::Keys::generate())
                .expect("signed"),
        };
        assert_debug_redacted!(sealed(), "SealedLocationFfi", NEEDLES);
        let seal = SealOutcomeFfi {
            sealed: Some(sealed()),
            held_by: None,
            refusal: None,
            replayed: vec![a_replayed_fix()],
            retry_after_ms: Some(u64::from(COUNTER)),
            errored: false,
            clock_rejected: Some(super::DeviceClockComplaintFfi::Ahead),
        };
        assert_debug_redacted!(seal, "SealOutcomeFfi", NEEDLES);
        let leave = LeaveOutcomeFfi {
            status: LeaveStatusFfi::Pending,
            retry_after_ms: Some(u64::from(COUNTER)),
            clock_rejected: Some(super::DeviceClockComplaintFfi::Behind),
        };
        assert_debug_redacted!(leave, "LeaveOutcomeFfi", NEEDLES);
        let withdrawn = || WithdrawnChangeFfi {
            mls_group_id: hex::decode(HEX_ID).expect("hex"),
            kind: WithdrawnKindFfi::RemoveMembers,
            outcome: WithdrawnOutcomeFfi::ReissuedAwaitingRelays,
        };
        assert_debug_redacted!(withdrawn(), "WithdrawnChangeFfi", NEEDLES);
        let requeued = || RequeuedRemovalFfi {
            mls_group_id: hex::decode(HEX_ID).expect("hex"),
            outcome: RequeueOutcomeFfi::PendingAwaitingRelays,
        };
        assert_debug_redacted!(requeued(), "RequeuedRemovalFfi", NEEDLES);
        let resume = |n: usize| ResumeOutcomeFfi {
            withdrawn: (0..n).map(|_| withdrawn()).collect(),
            requeued: (0..n).map(|_| requeued()).collect(),
            replayed: (0..n).map(|_| a_replayed_fix()).collect(),
            retry_after_ms: Some(u64::from(COUNTER)),
            errored: true,
            clock_rejected: Some(super::DeviceClockComplaintFfi::Ahead),
        };
        assert_debug_redacted!(resume(1), "ResumeOutcomeFfi", NEEDLES);
        assert_magnitude_invisible(
            &format!("{:?}", resume(1)),
            &format!("{:?}", resume(6)),
            "ResumeOutcomeFfi",
        );
        let reinvite = ReinviteFfi {
            mls_group_id: hex::decode(HEX_ID).expect("hex"),
            result: ReinviteResultFfi::ReissuedAwaitingRelays,
        };
        assert_debug_redacted!(reinvite, "ReinviteFfi", NEEDLES);
        let reinvited = |n: usize| ReinviteDrivenFfi {
            reinvites: (0..n)
                .map(|_| ReinviteFfi {
                    mls_group_id: hex::decode(HEX_ID).expect("hex"),
                    result: ReinviteResultFfi::ReissuedAwaitingRelays,
                })
                .collect(),
            drive: resume(n),
        };
        assert_debug_redacted!(reinvited(1), "ReinviteDrivenFfi", NEEDLES);
        assert_magnitude_invisible(
            &format!("{:?}", reinvited(1)),
            &format!("{:?}", reinvited(6)),
            "ReinviteDrivenFfi",
        );
        let notice = ChangeNoticeFfi {
            group_id: haven_core::nostr::mls::types::GroupId::new(
                hex::decode(HEX_ID).expect("hex"),
            ),
            notice: haven_core::nostr::mls::ChangeNotice::read(
                haven_core::nostr::mls::ChangeNote::WelcomeOwed.bit(),
                Some(u64::from(COUNTER)),
            ),
        };
        assert_debug_redacted!(notice, "ChangeNoticeFfi", NEEDLES);
    }

